package net.civeira.phylax.feature.observe.observedissuecomment.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AuthorVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property author of observed issue comment ")
  void test_author_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AuthorVO.tryFrom(null));
    Assertions.assertEquals("one", AuthorVO.from("one").getAuthor());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> AuthorVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AuthorVO.from("one").toString());
  }
}
